    last = calendar.monthrange(year, month)[1]
    if day not in values and not ("L" in specials and day == last):
        return False
    values, specials = fields[_DOW]
    weekday = (calendar.weekday(year, month, day) + 1) % 7
    if weekday in values:
        return True
    for special in specials:
        if special[1] != weekday:
            continue
        if special[0] == "L":
            if day + 7 > last:
                return True
        elif (day - 1) // 7 + 1 == special[2]:
            return True
    return False


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    fields = _parse(expr)
    return (when.minute in fields[0][0]
            and when.hour in fields[1][0]
            and when.month in fields[3][0]
            and _day_ok(fields, when.year, when.month, when.day))


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    fields = _parse(expr)
    minutes = sorted(fields[0][0])
    hours = sorted(fields[1][0])
    months = fields[3][0]
    try:
        limit = after + _LIMIT
    except OverflowError:
        limit = datetime.max
    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None
    year, month, day = start.year, start.month, start.day
    first = True
    while (year, month, day) <= (limit.year, limit.month, limit.day):
        if month not in months:
            day, first = 1, False
            month += 1
            if month > 12:
                year, month = year + 1, 1
                if year > 9999:
                    return None
            continue
        if _day_ok(fields, year, month, day):
            found = None
            if first:
                for hour in hours:
                    if hour < start.hour:
                        continue
                    floor = start.minute if hour == start.hour else 0
                    minute = next((m for m in minutes if m >= floor), None)
                    if minute is not None:
                        found = (hour, minute)
                        break
            else:
                found = (hours[0], minutes[0])
            if found:
                run = datetime(year, month, day, found[0], found[1])
                return run if run <= limit else None
        first = False
        day += 1
        if day > calendar.monthrange(year, month)[1]:
            day = 1
            month += 1
            if month > 12:
                year, month = year + 1, 1
                if year > 9999:
                    return None
    return None
